{
  "declined": "none",
  "criteria": [
    {
      "id": "task",
      "score": 5,
      "reason": "信件符合要求：以邀請朋友來台為主題，語氣親切並包含行程建議與住宿安排，滿足任務（invite and suggest activities）。"
    },
    {
      "id": "organization",
      "score": 5,
      "reason": "段落分明（開頭問候、行程建議、住宿說明、結尾請回覆），信息順序合理且連貫，例如“I have great news: my summer vacation starts in July, so I'd love to invite you to visit me in Taiwan.”"
    },
    {
      "id": "vocabulary",
      "score": 4,
      "reason": "用詞大多準確且自然（night markets, Taroko Gorge, take a train），但有一處用詞略顯口語或不精確（“meet you too”應為“meet you”或“meet you as well”）。"
    },
    {
      "id": "grammar",
      "score": 4,
      "reason": "句子結構整體良好且易懂，但有小錯誤與慣用語不自然，如“My parents are looking forward to meet you too.”"
    }
  ],
  "issues": [
    {
      "quote": "My parents are looking forward to meet you too.",
      "type": "grammar",
      "why": "此處應用動名詞或不定詞的慣用結構，正確的片語是 'look forward to' 後接動名詞（-ing），而非不定詞 'to meet'。此外 'too' 在句尾可改為 'as well' 或置於更自然位置。",
      "suggestion": "My parents are looking forward to meeting you."
    },
    {
      "quote": "you must try the stinky tofu, even though it smells terrible.",
      "type": "tone",
      "why": "雖然語法正確，但說 'smells terrible' 可能讓對方猶豫，對邀請語氣略顯負面；在邀請朋友嘗試地方小吃時，建議用更鼓勵和描述性的語句。",
      "suggestion": "you must try the stinky tofu — it's a local specialty with a strong smell but great taste."
    },
    {
      "quote": "I will take you to the night markets, and you must try the stinky tofu, even though it smells terrible.",
      "type": "cohesion",
      "why": "句子信息多且稍長，可用分句或標點讓語氣更自然，並避免一次塞太多資訊。",
      "suggestion": "I will take you to the night markets. You must try the stinky tofu; it has a strong smell but tastes great."
    }
  ],
  "more": [
    {
      "quote": "my summer vacation starts in July, so I'd love to invite you to visit me in Taiwan.",
      "type": "sentence",
      "why": "句子清楚但可更具體地提到可能的日期範圍以方便對方回覆。",
      "suggestion": "my summer vacation starts in July, so I'd love to invite you to visit me in Taiwan in July or August."
    },
    {
      "quote": "After that, we could take a train to Hualien and see Taroko Gorge.",
      "type": "word-choice",
      "why": "用 'see' 描述景點略為平淡，可用更生動的動詞來吸引朋友興趣。",
      "suggestion": "After that, we could take a train to Hualien and explore Taroko Gorge."
    },
    {
      "quote": "You can stay at my family's house, so you don't need to worry about the hotel.",
      "type": "grammar",
      "why": "'family's house' 文法上可以，但在口語書信中更自然的表達為 'my family's home' 或 'my parents' house'。",
      "suggestion": "You can stay at my parents' house, so you won't need to worry about a hotel."
    },
    {
      "quote": "Let me know which dates are good for you, and I will start planning.",
      "type": "tone",
      "why": "語氣友好，但可加一個提議日期選項，讓回覆更容易。",
      "suggestion": "Let me know which dates are good for you (e.g., early July or late July), and I will start planning."
    },
    {
      "quote": "I hope everything is going well in Melbourne!",
      "type": "word-choice",
      "why": "開頭友善但可稍微個人化（例如提到對方近況）會更貼心。",
      "suggestion": "I hope everything is going well in Melbourne and that you're enjoying your studies/work!"
    }
  ],
  "strengths": [
    {
      "quote": "There are so many things we could do together.",
      "why": "開門見山指出主要目的並自然引出接下來的行程建議，讓讀者知道信的重點。"
    },
    {
      "quote": "I will take you to the night markets, and you must try the stinky tofu, even though it smells terrible.",
      "why": "使用具體活動（night markets, stinky tofu）讓邀請內容生動且有吸引力。"
    }
  ],
  "summary": "寫得很自然、句子結構多數正確，接下來可以注意 'look forward to' 後接動名詞（meeting），並把某些句子改為更積極或更具體的描述（例如提供可選日期、用更生動的動詞 like 'explore'）。多練習這些小修改會讓信更自然並提高回覆率。"
}
